from robot.utils.robottime import timestr_to_secs

from .base import BaseInterface
from ..validators import IsString, IsOneOf
from ..converter import to_bool


class CustomerProcedures(BaseInterface):
    """
    Interface class for customer procedures
    """

    def check_amplifier(self, timeout=60, alias="default"):
        """Check amplifier.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: dict
        :return: amplifier info
        """

        timeout = timestr_to_secs(timeout)

        return self.store.get(alias).execute_customer_procedure(
            "checkAmplifier", {}, timeout)

    def check_anntenas(self, timeout=60, alias="default"):
        """Check anntenas.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: dict
        :return: anntenas info
        """

        timeout = timestr_to_secs(timeout)

        return self.store.get(alias).execute_customer_procedure(
            "checkAntennas", {}, timeout)

    def check_clock(self, timeout=60, alias="default"):
        """Check clock.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.


        :rtype: dict
        :return: clock
        """

        timeout = timestr_to_secs(timeout)

        return self.store.get(alias).execute_customer_procedure(
            "checkClock", {}, timeout)

    def check_fans(self, timeout=60, alias="default"):
        """Check fans.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: dict
        :return: fans info
        """

        timeout = timestr_to_secs(timeout)

